/* Visible historical reading, connected to the expanded network. */
(() => {
  'use strict';
  const host=document.getElementById('relationshipsReading');if(!host)return;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const source=new Map(window.DUNHUANG_NETWORK.sources.map(s=>[s.SourceId,s]));
  const cases=[
    {ids:['SUP_CONTACT1909','SUP_VIEW1909'],date:['Beijing · 1909','北京 · 1909年'],title:['Hearing about manuscripts, then seeing them','从听说写本，到亲眼查看'],
      chain:['Dong Kang → news to Luo Zhenyu; Dong Kang and Wang Shitong → access to Pelliot’s manuscripts','董康 → 告知罗振玉；董康、王式通 → 借观伯希和写本'],
      body:['Yun Yuding’s diary, quoted by Qin Hualin, describes Dong Kang and Wang Shitong gaining access through an American intermediary. Luo credits Dong with telling him about the manuscripts. Wang Guowei separately records viewing Pelliot’s Dunhuang manuscripts that autumn.','秦桦林引恽毓鼎日记，记董康、王式通经一位美国人介绍，借观伯希和所携写本。罗振玉也在当年文字中提到，消息来自董康。王国维则记下了自己当年秋天观看敦煌写本的经历。'],
      limit:['The exact dates and earlier source of the news are unresolved. These accounts may describe overlapping visits, not additional meetings or transfers.','各次查看的确切日期和最初消息来源尚未落实。这些记述可能有重合，不能据此多算会面次数，也不表示写本所有权转移。'],source:'G07',pages:['pp. 45, 50–51, including p. 51 n. 3','第45、50–51页，含第51页注③'],proof:['SUP_EV001','SUP_EV002','SUP_EV003']},
    {ids:['SUP_LETTER19091222','SUP_REPLY1910'],date:['22 December 1909 – circa August 1910','1909年12月22日—约1910年8月'],title:['Letters about making the texts available','通过通信商议刊布'],
      chain:['Dong Kang + Luo Zhenyu → Pelliot; Pelliot’s reply → Luo Zhenyu','董康、罗振玉 → 伯希和；伯希和回信 → 罗振玉'],
      body:['Dong and Luo jointly wrote to Pelliot about publication. Their letter was translated into French by Foreign Affairs personnel. A reply reached Luo around August 1910; Luo reported delayed photographic delivery and passed the French letter to Dong to arrange translation.','董康与罗振玉联名致信伯希和，商议敦煌文献的刊布，信由外务部人员译为法文。约1910年8月，伯希和回信寄达罗振玉。罗提到影片寄送延迟，并将法文来信交董康请人翻译。'],
      limit:['The reply’s arrival is approximately dated. The letters establish correspondence, not completed translation, receipt of photographs or transfer of original manuscripts.','回信到达时间为研究约定；这些记载证明通信联系，尚不能证明翻译已完成、照片已寄到或原卷已移交。'],source:'G07',pages:['p. 49, note 1','第49页注①'],proof:['SUP_EV004','SUP_EV005']},
    {ids:['SUP_PARIS191005'],date:['Paris · May 1910','巴黎 · 1910年5月'],title:['Zhang Yuanji learns about earlier British acquisitions','张元济获知英国人先得写本'],
      chain:['Pelliot → a conversation in Paris → Zhang Yuanji','伯希和 → 巴黎会面中的消息 → 张元济'],
      body:['Pan Sheng reconstructs this conversation from a letter Zhang wrote in March 1911. Zhang recalled learning from Pelliot that a British collector had reached Dunhuang before him and acquired many manuscripts. The network places the conversation in 1910; the later letter serves as evidence.','潘晟据张元济1911年3月的信，回述其1910年5月在巴黎与伯希和的会面。张从伯希和处得知，英国人比伯希和更早到敦煌，所得也多。图中记录的是1910年的会面，1911年的信仅作为证据。'],
      limit:['The quoted letter does not name the British collector. No direct Stein-to-Zhang communication or 1911 event is inferred.','所引文字没有写出这位英国取得者的姓名。图中不增加斯坦因直接向张元济传递消息的边，也不纳入1911年的通信事件。'],source:'L05',pages:['p. 136','第136页'],proof:['SUP_EV006']},
    {ids:['SUP_REQUEST19101203'],date:['Paris · 3 December 1910','巴黎 · 1910年12月3日'],title:['A request to see the collection','想要观看，未必能够实现'],
      chain:['Jin Shaocheng → letter requesting access → Pelliot','金绍城 → 请求观看收藏的信 → 伯希和'],
      body:['Jin Shaocheng, already connected to the 1909 Beijing banquet, wrote to Pelliot after arriving in Paris, asking to see his Dunhuang collection. Qin identifies the request in Jin’s travel diary and notes that the intended viewing did not take place.','参加过1909年北京宴会的金绍城抵达巴黎后，致信伯希和，希望观看其敦煌收藏。秦桦林据金的游历日记记述这次请求，并指出他的愿望最终未能实现。'],
      limit:['The graph marks a request. It does not represent a completed viewing or acquisition.','图中按“已提出的请求”标注，不画成已经参观或取得文献。'],source:'G07',pages:['p. 49 and note 2','第49页及注②'],proof:['SUP_EV007']}
  ];
  function render(){
    const zh=window.DUNHUANG_EXHIBITION.getState().lang==='zh',i=zh?1:0;
    host.setAttribute('aria-label',zh?'1909—1910年的学者联络与文献传播':'Scholarly contacts and manuscript knowledge, 1909–1910');
    host.innerHTML=`<p class="eyebrow">${zh?'北京与巴黎的学者联络':'SCHOLARLY CONTACTS IN BEIJING AND PARIS'}</p><h3>${zh?'消息、写本与照片，怎样进入学者的视野？':'How did scholars learn about and gain access to the manuscripts?'}</h3><p class="relationships-intro">${zh?'文献的流转之外，还有消息的转告、写本的借观，以及围绕刊布的通信。下列记述已接入上方网络；每一例都区分了已发生的活动、请求和尚未落实的结果。':'Alongside the movement of manuscripts were reports, opportunities to examine them and letters about publication. These accounts are connected to the network above, with actions distinguished from requests and unresolved outcomes.'}</p><div class="relationships-records">${cases.map((c,k)=>`<article class="relationships-record" data-supplement-case="${k}" data-proof="${c.proof.join(';')}"><p class="relationships-date">${esc(c.date[i])}</p><h4>${esc(c.title[i])}</h4><p class="relationships-chain">${esc(c.chain[i])}</p><p>${esc(c.body[i])}</p><p>${esc(c.limit[i])}</p><p class="relationships-citation"><a href="${esc(source.get(c.source).URL)}" target="_blank" rel="noopener noreferrer">${esc(source.get(c.source).Author)} (${esc(source.get(c.source).Year)}) ↗</a> · ${esc(c.pages[i])}<br>${zh?'依据为研究所引日记或信札；原件影像未独立核验。':'Based on diaries or letters cited in scholarship; original images have not been independently checked.'}</p>${c.ids.map(id=>{const ev=window.DUNHUANG_NETWORK.events.find(e=>e.EventId===id);return `<p><button class="relationships-locate" type="button" data-supplement-locate="${id}">${zh?'在完整网络中定位：':'Locate in the full network: '}${esc(zh?ev.LabelZH:ev.Label)} ↑</button></p>`;}).join('')}</article>`).join('')}</div><aside class="relationships-limits"><h4>${zh?'“有意隐瞒”，目前仍是需要辨析的解释':'Interpreting claims of deliberate concealment'}</h4><p>${zh?'潘晟指出，罗振玉1909年的发现史文字未谈斯坦因，并据此讨论当事人对消息的选择。他也列出叶昌炽1910年1月日记和《申报》同年10月2日涉及英国取得者的记载。因此，这里不把“伯希和帮助斯坦因隐瞒”画成已证实的人物关系，也不概括为当时中国无人知情。':'Pan discusses the omission of Stein from Luo’s 1909 discovery account and interprets the selective reporting of news. The same study cites Ye Changchi’s January 1910 diary and an October 1910 Shenbao report mentioning British acquisitions. This graph therefore does not assert a verified relationship of Pelliot concealing Stein’s activities, or claim that nobody in China knew about British acquisitions.'} <a href="${esc(source.get('L05').URL)}" target="_blank" rel="noopener noreferrer">${zh?'潘晟（2025），第135–136页 ↗':'Pan (2025), pp. 135–136 ↗'}</a></p></aside><p class="relationships-provenance">${zh?'补充范围仍为1900—1910年。原网络保留122个节点、136条关系；本次增加10个节点、21条关系和8条证据说明，其中新人物为张元济。新增6条活动记录不等于6次独立历史事件，部分查看记述可能重合。馆藏与保存部分涉及的后出研究不据此加入早期传播网络。':'The period remains 1900–1910. The original graph retains 122 nodes and 136 relationships. This addition supplies 10 nodes, 21 relationships and 8 evidence notes; Zhang Yuanji is the new person. Six activity records do not imply six distinct historical events: viewing accounts may overlap. Later conservation research is not added as early-network activity.'}</p><div class="relationships-downloads"><a href="assets/dunhuang-network-expanded.gexf" download>${zh?'补充版Gephi文件 ↓':'Expanded Gephi file ↓'}</a><a href="assets/network-expanded-nodes.csv" download>${zh?'节点表CSV ↓':'Nodes CSV ↓'}</a><a href="assets/network-expanded-edges.csv" download>${zh?'关系表CSV ↓':'Relationships CSV ↓'}</a><a href="assets/relationship-supplement-evidence.csv" download>${zh?'新增关系的来源与限度 ↓':'Sources and limits for the additions ↓'}</a></div>`;
    host.querySelectorAll('[data-supplement-locate]').forEach(button=>button.addEventListener('click',()=>{
      window.DUNHUANG_NETWORK_GUIDE.show('all');
      window.DUNHUANG_NETWORK_VIEW.selectNode(button.dataset.supplementLocate);
      window.DUNHUANG_NETWORK_VIEW.fitVisible();
      document.getElementById('networkShell').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
    }));
  }
  window.addEventListener('dunhuang:language',render);render();
})();
